package org.sleepwell.app;

import android.Manifest;
import android.content.*;
import android.content.pm.PackageManager;
import android.os.*;
import com.google.android.gms.common.*;
import com.google.android.gms.nearby.Nearby;
import com.google.android.gms.nearby.connection.*;
import org.json.*;
import java.util.*;

/** Explicit, single-peer measurement transport belonging to one already-active manual movement run. */
final class PairMotionRuntime {
    static final class Manual {final long session,start,wall,elapsed;final String token;Manual(long session,long start,long wall,long elapsed,String token){this.session=session;this.start=start;this.wall=wall;this.elapsed=elapsed;this.token=token;}}
    static final class Peer {final String id,name;Peer(String id,String name){this.id=id;this.name=name;}}
    static final class State {
        final boolean busy,connected,confirm,filter;final String message,code,name,link;final long session,uncertainty;final Double own,peer,filtered;final List<Peer> found;
        State(PairMotionRuntime r){busy=!r.closed;connected=r.connected&&r.peerStream!=null;confirm=!r.closed&&!r.code.isEmpty()&&!r.confirmed;filter=r.filterRequested;message=r.message;code=r.code;name=r.peerName;link=r.link;session=r.manual.session;uncertainty=r.alignment.fresh(now())?r.alignment.uncertainty():-1;own=r.latestOwn;peer=r.latestPeer;filtered=r.latestFiltered;found=List.copyOf(r.found.values());}
    }
    private static PairMotionRuntime active;
    private final Context application;private final ConnectionsClient client;private final Handler main=new Handler(Looper.getMainLooper());private final Manual manual;private final boolean filterRequested;private final UUID stream=UUID.randomUUID();private final String link=UUID.randomUUID().toString();
    private final Map<String,Peer> found=new LinkedHashMap<>();private final Map<Long,Long> pings=new HashMap<>();private final PairMotionClock alignment=new PairMotionClock();private final PairMotionFilter filter=new PairMotionFilter();private final ArrayDeque<Packet> peerPackets=new ArrayDeque<>();private final ArrayDeque<Window> waiting=new ArrayDeque<>(),inference=new ArrayDeque<>();
    private boolean closed,connected,confirmed;private String endpoint="",peerName="",code="",message="Preparing nearby connection…";private UUID peerStream;private PairMotionWriter writer;private long sequence,pingSequence,lastPeerSequence,lastPeerEnd,lastReceive=-1,lastPing=-1,started,aggregateFrom=-1,lastOwnEnd=-1,rateAt;private int messages;private long aggregateSamples;private double energy;private Double latestOwn,latestPeer,latestFiltered;private long generation=1;
    private static final String SERVICE="org.sleepwell.app.paired-motion.v1";
    private PairMotionRuntime(Context c,Manual manual,boolean filter){application=c.getApplicationContext();this.manual=manual;filterRequested=filter;client=Nearby.getConnectionsClient(application);}
    static State state(){assertMain();return active==null?null:new State(active);}
    static String prerequisite(Context c){if(TrackingService.pairManual()==null)return "Start a manual Phone movement recording on each phone first. Automatic and contactless recordings cannot pair.";if(GoogleApiAvailability.getInstance().isGooglePlayServicesAvailable(c)!=ConnectionResult.SUCCESS)return "Google Play services is unavailable or needs an update.";if(!missingPermissions(c).isEmpty())return "Nearby-device permission is needed. Older Android versions also require location permission for discovery.";return "";}
    static List<String> missingPermissions(Context c){List<String> needed=new ArrayList<>();if(Build.VERSION.SDK_INT>=31){needed.add(Manifest.permission.BLUETOOTH_SCAN);needed.add(Manifest.permission.BLUETOOTH_CONNECT);needed.add(Manifest.permission.BLUETOOTH_ADVERTISE);}if(Build.VERSION.SDK_INT>=33)needed.add(Manifest.permission.NEARBY_WIFI_DEVICES);else{needed.add(Manifest.permission.ACCESS_FINE_LOCATION);needed.add(Manifest.permission.ACCESS_COARSE_LOCATION);}needed.removeIf(p->c.checkSelfPermission(p)==PackageManager.PERMISSION_GRANTED);return needed;}
    static void begin(Context c,boolean host,boolean filter){assertMain();String problem=prerequisite(c);if(!problem.isEmpty())throw new IllegalStateException(problem);if(active!=null&&!active.closed)throw new IllegalStateException("Stop the current pairing before starting another.");Manual manual=TrackingService.pairManual();PairMotionRuntime next=new PairMotionRuntime(c,manual,filter);active=next;try{TrackingService.pairTransportChanged();next.start(host);}catch(RuntimeException failure){next.close("ERROR","Nearby pairing could not start. Check Bluetooth, Wi-Fi and permissions.");throw failure;}}
    static void connect(String id){assertMain();PairMotionRuntime r=active;if(r==null||!r.owns()||!r.endpoint.isEmpty()||!r.found.containsKey(id))return;r.endpoint=id;r.peerName=r.found.get(id).name;r.message="Connection requested. Compare the code on both phones.";long g=r.generation;r.client.stopDiscovery();try{r.client.requestConnection(r.localName(),id,r.lifecycle(g)).addOnFailureListener(error->r.fail(g,"Connection request failed. Tap Stop, then try again."));}catch(RuntimeException unavailable){r.fail(g,"Connection request failed. Review nearby permissions.");}}
    static void confirm(String expectedLink,String expectedCode){assertMain();PairMotionRuntime r=active;if(r==null||!r.owns()||!r.link.equals(expectedLink)||r.confirmed||r.code.isEmpty()||!r.code.equals(expectedCode))return;r.confirmed=true;r.message="Waiting for confirmation on the other phone…";long g=r.generation;try{r.client.acceptConnection(r.endpoint,r.payload(g)).addOnFailureListener(error->r.fail(g,"The connection could not be accepted."));}catch(RuntimeException denied){r.fail(g,"Nearby-device permission is unavailable.");}}
    static void stop(String expectedLink){assertMain();if(active!=null&&(expectedLink==null||active.link.equals(expectedLink)))active.close("USER","Pairing stopped. The original phone recording continues.");}
    static void recordingStopped(long session,String token,String reason){assertMain();if(active!=null&&active.manual.session==session&&active.manual.token.equals(token))active.close(reason,reason.equals("PAUSED")?"Recording paused. Pair again explicitly after resuming.":"Recording ended. Pairing stopped.");}
    static boolean transportOwned(long session,String token){return active!=null&&!active.closed&&active.manual.session==session&&active.manual.token.equals(token);}
    private boolean owns(){Manual current=TrackingService.pairManual();return !closed&&active==this&&current!=null&&current.session==manual.session&&current.start==manual.start&&current.token.equals(manual.token);}
    private boolean valid(long g){if(closed||g!=generation||active!=this)return false;if(!owns()){close("ENDED","The manual recording is no longer active. Pairing stopped.");return false;}return true;}
    private String localName(){return "SleepWell "+stream.toString().substring(0,4);}
    private void start(boolean host){long g=generation;if(host){message="Available as "+localName()+". On the other phone, choose Find phone.";client.startAdvertising(localName(),SERVICE,lifecycle(g),new AdvertisingOptions.Builder().setStrategy(Strategy.P2P_POINT_TO_POINT).build()).addOnFailureListener(error->fail(g,"Could not advertise. Check Bluetooth, Wi-Fi and nearby permissions."));}else{message="Searching. Choose Host pairing on the other phone.";client.startDiscovery(SERVICE,new EndpointDiscoveryCallback(){@Override public void onEndpointFound(String id,DiscoveredEndpointInfo info){main.post(()->{if(valid(g)&&endpoint.isEmpty()&&SERVICE.equals(info.getServiceId())&&found.size()<16)found.put(id,new Peer(id,safeName(info.getEndpointName())));});}@Override public void onEndpointLost(String id){main.post(()->{if(valid(g))found.remove(id);});}},new DiscoveryOptions.Builder().setStrategy(Strategy.P2P_POINT_TO_POINT).build()).addOnFailureListener(error->fail(g,"Could not search. Check Bluetooth, Wi-Fi and nearby permissions."));}main.postDelayed(heartbeat,1000);main.postDelayed(()->{if(valid(g)&&!connected)close("ERROR","Pairing timed out. Start a new connection when both phones are ready.");},120000);}
    private ConnectionLifecycleCallback lifecycle(long g){return new ConnectionLifecycleCallback(){
        @Override public void onConnectionInitiated(String id,ConnectionInfo info){main.post(()->{if(!valid(g))return;if(!endpoint.isEmpty()&&!endpoint.equals(id)){try{client.rejectConnection(id);}catch(RuntimeException ignored){}return;}endpoint=id;peerName=safeName(info.getEndpointName());code=info.getAuthenticationDigits();if(code==null||code.isBlank()||code.length()>32){fail(g,"A matching authentication code is unavailable. Pairing rejected.");return;}message="Compare this code on both phones. Confirm only if it matches.";client.stopAdvertising();client.stopDiscovery();found.clear();});}
        @Override public void onConnectionResult(String id,ConnectionResolution result){main.post(()->{if(!valid(g)||!endpoint.equals(id))return;if(!confirmed||!result.getStatus().isSuccess()){fail(g,"The connection was not confirmed by both phones.");return;}connected=true;code="";message="Connected. Waiting for the other phone’s movement stream…";send(PairMotionWire.hello(stream));});}
        @Override public void onDisconnected(String id){main.post(()->{if(valid(g)&&endpoint.equals(id))close("DISCONNECTED","The other phone disconnected. Raw phone movement remains; pair again to reconnect.");});}
    };}
    private PayloadCallback payload(long g){return new PayloadCallback(){@Override public void onPayloadReceived(String id,Payload payload){if(payload.getType()!=Payload.Type.BYTES)return;byte[] data=payload.asBytes();if(data==null||data.length>PairMotionWire.MAX_BYTES)return;byte[] copy=data.clone();main.post(()->{if(valid(g)&&connected&&confirmed&&endpoint.equals(id))receive(copy);});}@Override public void onPayloadTransferUpdate(String id,PayloadTransferUpdate update){if(update.getStatus()==PayloadTransferUpdate.Status.FAILURE)main.post(()->{if(valid(g)&&endpoint.equals(id))message="A nearby transfer failed. Missing readings remain gaps.";});}};}
    private void receive(byte[] bytes){long elapsed=now();if(elapsed<rateAt||elapsed-rateAt>=1000){messages=0;rateAt=elapsed;}if(++messages>16){close("ERROR","The paired phone sent too many messages. Connection stopped.");return;}try{PairMotionWire packet=PairMotionWire.read(bytes);if(packet.type==PairMotionWire.HELLO){if(peerStream!=null&&!peerStream.equals(packet.stream)){close("ERROR","The peer stream changed. Start a new explicit pairing.");return;}if(peerStream==null){peerStream=packet.stream;Manual current=TrackingService.pairManual();started=current.wall;writer=new PairMotionWriter(application,new JSONObject().put("link",link).put("session",manual.session).put("record_start",manual.start).put("started",started).put("ended",JSONObject.NULL).put("local_stream",stream.toString()).put("peer_stream",peerStream.toString()).put("filter_requested",filterRequested?1:0).put("protocol",1).put("close_reason",""),problem->{if(!closed)close("ERROR",problem);});message="Connected · aligning the two clocks";ping();}return;}if(peerStream==null||!peerStream.equals(packet.stream))return;
        if(packet.type==PairMotionWire.PING){send(PairMotionWire.pong(stream,packet.sequence,packet.a,elapsed,now()));return;}
        if(packet.type==PairMotionWire.PONG){Long sent=pings.remove(packet.sequence);if(sent!=null&&sent==packet.a)alignment.sample(packet.a,packet.b,packet.c,elapsed);return;}
        if(packet.type!=PairMotionWire.MOTION||packet.sequence<=lastPeerSequence||packet.a<lastPeerEnd)return;lastPeerSequence=packet.sequence;lastPeerEnd=packet.b;Manual current=TrackingService.pairManual();long received=current.wall;Long alignedFrom=null,alignedTo=null,offset=null,uncertainty=null;String quality="UNALIGNED";
        if(alignment.fresh(elapsed)){long fromElapsed=alignment.local(packet.a),toElapsed=alignment.local(packet.b);long from=received-(elapsed-fromElapsed),to=received-(elapsed-toElapsed);if(from>=manual.start&&to<=received+1000&&to>=received-15000){alignedFrom=from;alignedTo=to;offset=alignment.offset();uncertainty=alignment.uncertainty();quality=packet.movement==null?"MISSING":elapsed-toElapsed>5000?"STALE":"ALIGNED";}}
        JSONObject row=new JSONObject().put("link",link).put("seq",packet.sequence).put("remote_start",packet.a).put("remote_end",packet.b).put("received",received).put("aligned_start",nullable(alignedFrom)).put("aligned_end",nullable(alignedTo)).put("movement",nullable(packet.movement)).put("samples",packet.samples).put("offset_ms",nullable(offset)).put("uncertainty_ms",nullable(uncertainty)).put("quality",quality);writer.packet(row);lastReceive=elapsed;latestPeer=quality.equals("ALIGNED")?packet.movement:null;
        if(quality.equals("ALIGNED")){peerPackets.add(new Packet(packet.sequence,alignedFrom,alignedTo,packet.movement,packet.samples,uncertainty));while(peerPackets.size()>16)peerPackets.removeFirst();}if(!quality.equals("ALIGNED"))filter.gap();message=quality.equals("ALIGNED")?filterRequested?"Connected · experimental filter waits for enough matched movement":"Connected · raw paired movement":quality.equals("UNALIGNED")?"Connected · clock alignment unavailable; raw fallback":"Connected · peer measurement missing or late; raw fallback";
    }catch(JSONException|IllegalArgumentException malformed){close("ERROR","The other phone sent an unsupported measurement. Connection stopped.");}}
    private final Runnable heartbeat=new Runnable(){@Override public void run(){long g=generation;if(!valid(g))return;if(!missingPermissions(application).isEmpty()){close("ERROR","Nearby permission was removed. Pairing stopped; raw recording continues.");return;}if(connected&&peerStream!=null&&(lastPing<0||now()-lastPing>=30000))ping();if(connected&&lastReceive>=0&&now()-lastReceive>15000){latestPeer=null;latestFiltered=null;filter.gap();message="No fresh peer movement. Recording gaps and using raw movement.";}main.postDelayed(this,1000);}};
    private void ping(){if(!owns()||!connected)return;if(pings.size()>4)pings.clear();long sequence=++pingSequence,sent=now();pings.put(sequence,sent);lastPing=sent;send(PairMotionWire.ping(stream,sequence,sent));}
    private void send(PairMotionWire packet){if(!owns()||!connected||endpoint.isEmpty())return;long g=generation;try{client.sendPayload(endpoint,Payload.fromBytes(packet.bytes())).addOnFailureListener(error->{if(valid(g))message="Nearby transfer failed. Missing readings remain gaps.";});}catch(RuntimeException denied){fail(g,"Nearby transfer is unavailable. Raw movement recording continues.");}}
    static void sample(Manual expected,long from,long to,long elapsed,Double movement,int samples){assertMain();PairMotionRuntime r=active;if(r==null||!r.owns()||r.writer==null||expected==null||r.manual.session!=expected.session||!r.manual.token.equals(expected.token))return;r.ownSample(from,to,elapsed,movement,samples);}
    private void ownSample(long from,long to,long elapsed,Double movement,int samples){if(from<started||from<lastOwnEnd||to<=from||to-from>15000||samples<0||movement!=null&&(!Double.isFinite(movement)||movement<0||movement>1000)){resetAggregate();return;}if(lastOwnEnd>=0&&from!=lastOwnEnd)resetAggregate();lastOwnEnd=to;if(aggregateFrom<0)aggregateFrom=from;if(samples>0&&movement!=null){energy+=movement*movement*samples;aggregateSamples+=samples;}if(to-aggregateFrom<5000)return;if(to-aggregateFrom>15000||aggregateSamples>1000){resetAggregate();return;}Double own=aggregateSamples==0?null:Math.sqrt(energy/aggregateSamples);long first=aggregateFrom;int n=(int)aggregateSamples;resetAggregate();latestOwn=own;long seq=++sequence;send(PairMotionWire.motion(stream,seq,elapsed-(to-first),elapsed,own,n));Window window=new Window(first,to,own,n);waiting.add(window);long g=generation;main.postDelayed(()->{if(valid(g)&&waiting.remove(window))finishWindow(window);},1500);}
    private void resetAggregate(){aggregateFrom=-1;aggregateSamples=0;energy=0;}
    private void finishWindow(Window window){if(writer==null)return;Packet match=null;long overlap=0;for(Packet p:peerPackets){long length=Math.max(0,Math.min(window.to,p.to)-Math.max(window.from,p.from));if(length>overlap){overlap=length;match=p;}}boolean fresh=alignment.fresh(now())&&match!=null&&overlap>=Math.round((window.to-window.from)*.8)&&window.own!=null;Double filtered=null;String quality=window.own==null?"LOW_COVERAGE":!alignment.fresh(now())?"WAITING_SYNC":"PEER_MISSING";if(fresh){filtered=filter.apply(window.own,match.value,filterRequested);quality=filtered==null?"FRESH_RAW":"COMMON_REDUCED";}else filter.gap();window.filtered=filtered;window.matched=fresh;latestFiltered=filtered;
        try{writer.window(new JSONObject().put("link",link).put("start",window.from).put("time",window.to).put("own",nullable(window.own)).put("own_samples",window.samples).put("peer_seq",fresh?match.sequence:JSONObject.NULL).put("peer",fresh?match.value:JSONObject.NULL).put("filtered",nullable(filtered)).put("quality",quality).put("uncertainty_ms",fresh?match.uncertainty:JSONObject.NULL));}catch(JSONException impossible){close("ERROR","Paired measurements could not be encoded.");return;}inference.add(window);while(inference.size()>48)inference.removeFirst();if(filtered!=null)message="Connected · experimental shared-motion reduction active";
    }
    static double inference(long session,String token,long from,long to,double raw){assertMain();PairMotionRuntime r=active;if(r==null||!r.owns()||!r.filterRequested||r.manual.session!=session||!r.manual.token.equals(token)||!r.alignment.fresh(now())||r.lastReceive<0||now()-r.lastReceive>10000)return raw;long coverage=0;double original=0,reduced=0;for(Window w:r.inference){long duration=Math.max(0,Math.min(to,w.to)-Math.max(from,w.from));if(duration<=0||!w.matched||w.own==null)continue;coverage+=duration;original+=w.own*w.own*duration;double value=w.filtered==null?w.own:w.filtered;reduced+=value*value*duration;}if(coverage<(to-from)*.8||original<=1e-12)return raw;return raw*Math.max(.5,Math.min(1,Math.sqrt(reduced/original)));}
    private void fail(long g,String problem){if(valid(g))close("ERROR",problem);}
    private void close(String reason,String text){if(closed)return;Manual current=TrackingService.pairManual();long ended=current!=null&&current.session==manual.session&&current.token.equals(manual.token)?current.wall:manual.wall+Math.max(0,now()-manual.elapsed);while(!waiting.isEmpty())finishWindow(waiting.remove());closed=true;generation++;message=text;code="";found.clear();main.removeCallbacksAndMessages(null);filter.gap();latestPeer=latestFiltered=null;try{client.stopAdvertising();}catch(RuntimeException ignored){}try{client.stopDiscovery();}catch(RuntimeException ignored){}try{client.stopAllEndpoints();}catch(RuntimeException ignored){}if(writer!=null)writer.close(ended,reason);try{TrackingService.pairTransportChanged();}catch(RuntimeException ignored){/* Existing capture type remains owned by TrackingService. */}}
    private static String safeName(String name){if(name==null)return "Nearby phone";String clean=name.replaceAll("[\\p{Cntrl}]","").strip();return clean.length()>48?clean.substring(0,48):clean.isEmpty()?"Nearby phone":clean;}
    private static Object nullable(Object value){return value==null?JSONObject.NULL:value;}private static long now(){return SystemClock.elapsedRealtime();}private static void assertMain(){if(Looper.myLooper()!=Looper.getMainLooper())throw new IllegalStateException("Open pairing on the current screen.");}
    private static final class Packet{final long sequence,from,to,uncertainty;final double value;final int samples;Packet(long sequence,long from,long to,double value,int samples,long uncertainty){this.sequence=sequence;this.from=from;this.to=to;this.value=value;this.samples=samples;this.uncertainty=uncertainty;}}
    private static final class Window{final long from,to;final Double own;final int samples;Double filtered;boolean matched;Window(long from,long to,Double own,int samples){this.from=from;this.to=to;this.own=own;this.samples=samples;}}
}
